mapper.select:
SELECT id, tenant_id, user_no, dept_id, user_name, phone, sex, bithday, address, wotk_state, user_state, entry_time, resignation_time, referrer_id, create_time, update_time, version, email, `status`, remark, user_type FROM `user`
AND dept_id = #{query.deptId}
AND user_name LIKE CONCAT('%', #{query.userName}, '%')
AND phone = #{query.phone}
AND user_type = #{query.userType}
AND delete_flag = 'ok'
